class Solution {public:int cherryPickup(vector<vector<int>>& grid) {int r = grid.size();int cols = grid[0].size();vector<vector<vector<int>>> dp(grid.size(), vector<vector<int>>(grid[0].size(),vector<int>(grid[0].size(), -1)));for (int j = 0; j < cols; j++) {for (int k = 0; k < cols; k++) {dp[r - 1][j][k] =(j == k) ? grid[r - 1][j] : (grid[r -1][j] + grid[r-1][k]);}}for(int i = r - 2; i >= 0; i--){for(int j = 0; j < cols; j++){for(int k = 0; k < cols; k++){int res = INT_MIN;for(int d = j - 1; d < j + 2; d++){for(int p = k - 1; p < k + 2; p++){if(d >=0 && d < cols && p >= 0 && p < cols){int sum1 = (j == k) ? (grid[i][j] + dp[i + 1][d][p]) : grid[i][j] + grid[i][k] + dp[i + 1][d][p];res = max(res, sum1);}}}dp[i][j][k] = res;}}}return dp[0][0][cols - 1];}};
